#include <iostream> #include <map> using namespace std; int main() {     map<int, string> students;     int choice, id;     string name;     do {         cout << "\n1. Add\n2. Display\n3. Search\n4. Delete\n0. Exit\n";         cin >> choice;         switch(choice) {             case 1:                 cout << "Enter ID and Name: ";                 cin >> id >> name;                 students[id] = name;                 break;              case 2:                 for(auto x : students)                     cout << x.first << " " << x.second << endl;                 break;              case 3:                 cout << "Enter ID: ";                 cin >> id;                 if(students.find(id) != students.end())                     cout << students[id];                 else                     cout << "Not Found";                 break;             case 4:                 cout << "Enter ID: ";                 cin >> id;                 students.erase(id);                 break;         }      } while(choice != 0); } #include <iostream> #include <map> using namespace std; int main() {     map<int, string> students;     int choice, id;     string name;     do {         cout << "\n1. Add\n2. Display\n3. Search\n4. Delete\n0. Exit\n";         cin >> choice;         switch(choice) {             case 1:                 cout << "Enter ID and Name: ";                 cin >> id >> name;                 students[id] = name;                 break;              case 2:                 for(auto x : students)                     cout << x.first << " " << x.second << endl;                 break;              case 3:                 cout << "Enter ID: ";                 cin >> id;                 if(students.find(id) != students.end())                     cout << students[id];                 else                     cout << "Not Found";                 break;             case 4:                 cout << "Enter ID: ";                 cin >> id;                 students.erase(id);       